interface Payment{void makePayment(double a);}class UPI implements Payment{public void makePayment(double a){System.out.println("UPI "+a);}}class CreditCard implements Payment{public void makePayment(double a){System.out.println("Card "+a);}}class PaymentPolymorphism{public static void main(String[] x){Payment p=new UPI();p.makePayment(1000);p=new CreditCard();p.makePayment(2000);}}